export const defaults={mode:'wind',bearing:180,count:48,radius:4,crownHeight:8,date:'2026-07-15',hour:12,height:1,eui:120,saving:20,pv:0,factor:.421,opacity:.48,playback:1,field:'speed',contrast:20,playing:true};
export function carbon(area,s){const baseline=area*s.eui*s.factor/1000;const proposal=baseline*(1-s.saving/100)*(1-s.pv/100);return {baseline,proposal,change:baseline?100*(proposal/baseline-1):0};}
export function windKey(s,baseline=false){return `${s.bearing}_${baseline?0:s.count}_${baseline||s.count===0?4:s.radius}`;}
export function treeShade(base,meta,trees,s,sun){const out=new Uint8Array(base);if(sun.altitude<=0){out.fill(1);return out;}const sin=Math.sin(sun.altitude),dx=Math.sin(sun.azimuth)/Math.tan(sun.altitude),dy=Math.cos(sun.azimuth)/Math.tan(sun.altitude),angle=Math.atan2(dy,dx),ca=Math.cos(angle),sa=Math.sin(angle),major=s.radius/sin,minor=s.radius;
for(const t of trees.slice(0,s.count)){const cx=t.x+dx*s.crownHeight,cy=t.y+dy*s.crownHeight;const minI=Math.max(0,Math.floor((cx-major-meta.x0)/meta.dx)),maxI=Math.min(meta.nx-1,Math.ceil((cx+major-meta.x0)/meta.dx)),minJ=Math.max(0,Math.floor((cy-major-meta.y0)/meta.dx)),maxJ=Math.min(meta.ny-1,Math.ceil((cy+major-meta.y0)/meta.dx));for(let j=minJ;j<=maxJ;j++)for(let i=minI;i<=maxI;i++){const x=meta.x0+(i+.5)*meta.dx-cx,y=meta.y0+(j+.5)*meta.dx-cy;if(((x*ca+y*sa)/major)**2+((-x*sa+y*ca)/minor)**2<=1)out[j*meta.nx+i]=1;}}
return out;}
export function fraction(a,mask){let total=0,n=0;for(let i=0;i<a.length;i++)if(mask[i]){n++;total+=a[i];}return n?total/n:0;}
export function cleanState(raw){const s={...defaults};const discrete={mode:['wind','shade','carbon'],bearing:[0,45,90,135,180,225,270,315],count:[0,24,48],radius:[2,4,6],date:['2026-03-21','2026-07-15','2026-12-21'],hour:[9,10,11,12,13,14,15,16],height:[.75,1,1.25,1.5],field:['speed','difference']};for(const [k,v] of Object.entries(discrete))if(v.includes(raw?.[k]))s[k]=raw[k];const bounds={crownHeight:[4,14],eui:[40,240],saving:[0,60],pv:[0,80],factor:[.1,.6],opacity:[.08,1],playback:[.25,3],contrast:[1,30]};for(const [k,[a,b]] of Object.entries(bounds))if(Number.isFinite(raw?.[k]))s[k]=Math.max(a,Math.min(b,raw[k]));return s;}
